// src/perekop/services/core.service.ts
function coreService() {
  TabServiceInstance.onChange((activeId, tabs) => {
    logger.info("[TAB]", activeId);
    store.set({
      tabService: {
        current: activeId || "",
        all: tabs.map((tab) => tab.id)
      }
    });
  });
  const watcher = PerekopLogWatcher.getInstance();
  watcher.init(
    async () => {
      const logs = await PerekopShellMethods.checkLogs();
      if (logs.success) {
        return logs.data;
      }
      return "";
    },
    {
      intervalMs: 3e3,
      onNewLog: (line) => {
        if (line.toLowerCase().includes("[error]") || line.toLowerCase().includes("[fatal]")) {
          ui.addNotification("Perekop Error", E("div", {}, line), "error");
        }
      }
    }
  );
  watcher.start();
}

