// src/helpers/normalizeCompiledVersion.ts
function normalizeCompiledVersion(version) {
  if (version.includes("COMPILED")) {
    return "dev";
  }
  return version;
}

// src/helpers/removeVersionPrefix.ts
function removeVersionPrefix(version) {
  return version.replace(/^v/, "");
}

// src/perekop/tabs/diagnostic/helpers/getPerekopVersionRow.ts
function isUnknownVersion(version) {
  return version === "unknown" || version === _("unknown");
}
function getPerekopVersionRow(diagnosticsSystemInfo) {
  const loading = diagnosticsSystemInfo.loading;
  const unknown = isUnknownVersion(diagnosticsSystemInfo.perekop_version);
  const hasActualVersion = Boolean(diagnosticsSystemInfo.perekop_latest_version) && !isUnknownVersion(diagnosticsSystemInfo.perekop_latest_version);
  const version = normalizeCompiledVersion(
    diagnosticsSystemInfo.perekop_version
  );
  const isDevVersion = version === "dev";
  if (loading || unknown || !hasActualVersion || isDevVersion) {
    return {
      key: "Perekop",
      value: version
    };
  }
  if (removeVersionPrefix(version) !== removeVersionPrefix(diagnosticsSystemInfo.perekop_latest_version)) {
    return {
      key: "Perekop",
      value: version,
      tag: {
        label: _("Outdated"),
        kind: "warning"
      }
    };
  }
  return {
    key: "Perekop",
    value: version,
    tag: {
      label: _("Latest"),
      kind: "success"
    }
  };
}

